CREATE TABLE capital_source_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), institution_id uuid NOT NULL REFERENCES institutional_profiles(id) ON DELETE CASCADE, capital_types jsonb NOT NULL DEFAULT '[]'::jsonb, sectors jsonb NOT NULL DEFAULT '[]'::jsonb, geographies jsonb NOT NULL DEFAULT '[]'::jsonb, minimum_readiness integer NOT NULL DEFAULT 60, instrument_notes text, eligibility_notes text, evidence_urls jsonb NOT NULL DEFAULT '[]'::jsonb, last_verified_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(institution_id));